			}
		}catch(Exception e){}
		for(byte i=-127;i<73;i++){
			if(k[i+127]>0){System.out.println(k[i+127]);}
			else{break;}
		}
    }
	public static byte dig(int a){
		byte d = 0;
		while(true){
			if(a>=10){
				d++;
				a/=10;
			}
			else{return (byte)((int)d+1);}
		}
	}
}

