	static void sort(int[] data){
		int min, tmp;
		for(int i=0; i<data.length; i++){
			min = i;
			for(int j=i+1; j<data.length; j++)
				if(data[min]>data[j]) min = j;
			tmp = data[i];
			data[i] = data[min];
			data[min] = tmp;
		}
	}	
}

