		for(int h=nums.length-1;h>0;h--){
			for(int i=1;i<=h;i++){
				if(nums[i]>nums[i-1]){
					int tmp=nums[i];
					nums[i]= nums[i-1];
					nums[i-1]=tmp;
				}
			}
		}
		return nums;
