	public static String isRightTriangle(int a, int b ,int c){
		if(a>b){
			int k = a;
			a = b;
			b = k;
		}
		if(b>c){
			int k = b;
			b = c;
			c= k;
		}

		if(c*c == a*a+b*b)
			return "YES";
		else
			return "NO";
	}

}

