            int min = getMIN(A, B, max);

            System.out.println(max + " " + min);



        }
    }

    private static int getMAX(int A, int B) {
        for (int i = A; A > 0; i--) {
            if (A % i == 0 && B % i == 0) {
                return i;
            }
        }
        return 1;
    }
