		int	nGcd = gcd(aMatrix[0], aMatrix[1]);							// 最大公約数
		int	nLcm = (nGcd == 0) ? 0 : aMatrix[0] * (aMatrix[1] / nGcd);	// 最小公倍数

		System.out.printf("%d %d\n", nGcd, nLcm);
	}

	private static int gcd(int n1, int n2) {
		int		nGcd = 0;			// 最大公約数
		int[]	aNum = new int[3];	// 計算用の配列

		if (n1 == n2) {
			nGcd = n1;
