		else {
			aNum[0] = n1;
			aNum[1] = n2;
			aNum[2] = Math.abs(n1 - n2);

			Arrays.sort(aNum);
			nGcd = gcd(aNum[0], aNum[1]);
		}

		return nGcd;
	}
}

