			}
			solve(a, b);
		}
	}

	public void solve(int a, int b) {
		int gcdRes = gcd(a, b);
		int lcmRes = lcm(a, b, gcdRes);

		System.out.println(gcdRes + " " + lcmRes);
	}

	private int gcd(int a, int b){
		if(a%b == 0)
			return b;

		return gcd(b, a%b);
	}

	private int lcm(int a, int b, int gcdNum){
		return (int)(((long)a*b) / gcdNum);
	}

	/** バグがある? **/
	private int lcm(int a, int b){
		if(a<=3){
			if(a==b)
				return a;
			else
				return a*b;
		}else if(a%b==0){
			return a;
		}

		int r = b;
		for(int i=2;i*i<=a;i++){
			int aFact = 1;
			while(a%i==0){
				a = a/i;
				aFact*=i;
			}

			int bFact = 1;
			while(b%i==0){
				b = b/i;
				bFact*=i;
			}

			if(aFact>bFact)
				r *= (aFact/bFact);
		}
		return r*a;

	}


}

