		}
	}

	public static int getCommonDivider(int a, int b)
	{
		if (b == 0) return a;
		int q = a % b;
		return getCommonDivider(b, q);
	}

	public static int getCommonMultiplier(int a, int b)
	{
		int v = getCommonDivider(a, b);
		int va = a / v;
		int vb = b / v;
		return v*(va*vb);
	}
}

