    public static int getGCD(int x,int y){
    	int temp;
    	while((temp = x % y) != 0){
    		x = y;
    		y = temp;
    	}
    	return y;
    }
    public static int[] strToInt(String[] strArray){
    	int[] numArray = new int[strArray.length];
    	for(int i=0; i<strArray.length; i++){
