		}

		System.out.println(count);
	}

	public static long searchMinDivisor(long n){
		long p;
		boolean isSucceed = false;
		for(p = 2; p * p <= n; p++){
			if(n % p == 0){
				isSucceed = true;
				break;
			}
		}
		if(!isSucceed){
			p = n;
		}
		return p;
	}
}

