			r[i] = stdIn.nextInt();

		int ans = calcMaxDifference(r, n);
		System.out.println(ans);
	}

	public static int calcMaxDifference(int[] r, int n) {
		int max = r[1] - r[0];
		int rmin = r[0];

		for (int i = 1; i < n; i++) {
			max = (max > r[i] - rmin ? max : r[i] - rmin);
			rmin = (rmin < r[i] ? rmin : r[i]);
		}
		return max;
	}
}

