import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int size = Integer.parseInt(scanner.next());
        int[] array = new int[size];
        for (int i = 0; i < size; i++) {
            array[i] = Integer.parseInt(scanner.next());
        }

        boolean flag = true;
        int swapCount = 0;
        while (flag) {
            flag = false;
            for (int j = size - 1; j > 0; j--) {
                if (array[j] < array[j - 1]) {
                    swap(j, j - 1, array);
                    swapCount++;
                    flag = true;
                }
            }
        }
        System.out.println(concat(array));
        System.out.println(swapCount);
    }

    private static String concat(int[] array) {
        StringJoiner joiner = new StringJoiner(" ");
        for (int value : array) {
            joiner.add(String.valueOf(value));
        }
        return joiner.toString();
    }

    private static void swap(int i, int j, int[] array) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

import java.util.Scanner;
import java.util.List;
import java.util.ArrayList;

public class Main {
  public static void main (String[] args) {
    Scanner scanner = new Scanner(System.in);
    int N = scanner.nextInt();
    List<Integer> numbers = new ArrayList<Integer>();
    for (int i = 0; i < N; ++i) {
      numbers.add(scanner.nextInt());
    }

    int temp, count = 0;
    for (int i = 0; i + 1 < N; ++i) {
      for (int j = 0; j + 1 < N - i; ++j) {
        if (numbers.get(j) > numbers.get(j + 1)) {
          temp = numbers.get(j + 1);
          numbers.set(j + 1, numbers.get(j));
          numbers.set(j, temp);
          ++count;
        }
      }
    }

    if (N == 0) count = 1;

    for (int i = 0; i < N - 1; ++i) System.out.print(numbers.get(i) + " ");
    System.out.println(numbers.get(N - 1) + "\n" + count);
  }
}

import java.util.Scanner;

public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int A[] = new int[N];
		for(int i=0;i<N;i++){
			A[i] = sc.nextInt();
		}
		bubbleSort(A,N);
	}
	public static void bubbleSort(int[] A,int N){
		int flag = 1,count=0;
		while(flag==1){
			flag = 0;
			int i=0;
			for(int j=i;j<N-1;j++){
				if(A[j+1]<A[j]){
					int c = A[j+1];
					A[j+1] = A[j];
					A[j] = c;
					count++;
					flag = 1;
				}
			}
			i++;
		}
		for(int i=0;i<N;i++){
			System.out.print(A[i]);
			if(i!=N-1)System.out.print(" ");
		}
		System.out.printf("\n%d\n",count);
	}
}

