                        swap(bSort,j,j-1);
                        count++;
                    }
                }
            }
            PrintOut(bSort,n);
            System.out.println(count);
        }
    }

    public static void swap(int[] a,int i,int j){
        int t = a[j];a[j] = a[i];a[i] = t;
    }

    public static void PrintOut(int[] a,int n){
        for(int i = 0;i < n;i++){
            System.out.print(a[i] + ((i == n-1)?"\n":" "));
        }
    }
}

