    public SelectionSort(int[] selSort){
        this.selSort = selSort;
    }

    int count = 0;
    public void changeOfSNum(){
        int maxNum = 0;
        int flag = 0;
        for(int i = 0, j; i < selSort.length; i++){
            maxNum = selSort[i];
            j = i + 1;
            while(j < selSort.length){
                if(selSort[j] < selSort[i]){
                    selSort[i] = selSort[j];
                    flag = j;
                }
                j++;
            }
            if(maxNum != selSort[i]){
                selSort[flag] = maxNum;
                count++;
            }
        }
