public class Main {
    static void swap(int[] A, int i, int j) {
        int tmp = A[i];
        A[i] = A[j];
        A[j] = tmp;
    }

    static int selectionSort(int[] A, int N) {
        int count = 0;
        for(int i = 0; i < N; i++) {
            int minj = i;
            for(int j = i; j < N; j++) {
                if(A[j] < A[minj]) minj = j;
            }
            if(i != minj) {
                swap(A, i, minj);
                count++;
            }
        } 
        return count;
    }

