	public static void selectionSort(int[] arr, int n) {
		int count = 0;
		for (int i = 0; i < n; i++) {
			int minj = i;
			for (int j = i; j < n; j++) {
				if (arr[j] < arr[minj]) {
					minj = j;
				}
			}
			if (i != minj) {
				count++;
			}
			int tmp = arr[i];
