            s = inputChar[i];
            switch (s){
                case "+":
                    a = pop();
                    b = pop();
                    push(a + b);
                    break;

                case "-":
                    a = pop();
                    b = pop();
                    push(b-a);
                    break;

                case "*":
                    a = pop();
                    b = pop();
                    push(a * b);
                    break;

                default:
                    push(Integer.parseInt(s));
            }
        }

        System.out.println(pop());

    }

