                stack.push(n);
            } else if (op.equals("-")) {
                int n = -1 * stack.pop() + stack.pop();
                stack.push(n);
            } else if (op.equals("*")) {
                int n = stack.pop() * stack.pop();
                stack.push(n);
            } else {
                stack.push(Integer.parseInt(op));
            }
        }

        System.out.println(stack.pop());
    }
}

