                    first = stack.get(stack.size() - 2);
                    second = stack.get(stack.size() - 1);
                    int a = first + second;
                    stack.remove(stack.size() - 1);
                    stack.remove(stack.size() - 1);
                    stack.add(a);
                    break;
                case "-":
                    first = stack.get(stack.size() - 2);
                    second = stack.get(stack.size() - 1);
                    int b = first - second;
                    stack.remove(stack.size() - 1);
                    stack.remove(stack.size() - 1);
                    stack.add(b);
                    break;
                case "*":
                    first = stack.get(stack.size() - 2);
                    second = stack.get(stack.size() - 1);
                    int c = first * second;
                    stack.remove(stack.size() - 1);
                    stack.remove(stack.size() - 1);
                    stack.add(c);
                    break;
                default:
                    stack.add(Integer.parseInt(value));
