class Stack{
    int top;
    final int MAX;
    int S[];

    public Stack(int MAX){
	top=0;
	this.MAX=MAX;
	S=new int[MAX];
    }
    public boolean isEmpty(){
	return top==0;
    }

    public boolean isFull(){
	return top>=MAX-1;
    }

    public void push(int x){
	if(!isFull()){
	    top++;
	    S[top]=x;
	}
    }
    public int pop(){
	if(!isEmpty()){
	    top--;
	    return S[top+1];
	}
	return -1;
    }
}

