	public static void main(String args[]) {
		Stack<Integer> myStack = new Stack<Integer>();

		Scanner in = new Scanner(System.in);
		String problem = in.nextLine();

		Scanner problemScanner = new Scanner(problem);

		while(problemScanner.hasNext()) {
			if(problemScanner.hasNextInt()) {
				myStack.push(problemScanner.nextInt());
			}
			else {
				String operator = problemScanner.next();

				int a = myStack.pop();
				int b = myStack.pop();

				switch(operator) {
				case "+" : myStack.push(a + b);
				break;
				case "-" : myStack.push(b - a);
				break;
				case "*" : myStack.push(b * a);
				break;
				default : break;
				}
			}


		}

		System.out.println(myStack.pop());




	}

}

import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        // Your code here!
        Scanner sc = new Scanner(System.in);
        Deque<Integer> stack = new ArrayDeque<Integer>();

        while(sc.hasNext()) {
            String n = sc.next();
            if (n.equals("+")){
                int a = stack.pop()+stack.pop();
                stack.push(a);
            } else if (n.equals("-")){
                int x = stack.pop();
                int y = stack.pop();
                int a = y-x;
                stack.push(a);
            } else if (n.equals("*")) {
                int a = stack.pop()*stack.pop();
                stack.push(a);
            } else {
                stack.push(Integer.parseInt(n));
            }

        }
        System.out.println(stack.pop());

    }
}

