		}

		// ラウンドロビンスケジューリング
		while(!timeQueue.isEmpty()) {
			if(timeQueue.peek() > quantum) {
				timeQueue.add(timeQueue.poll() - quantum);
				nameQueue.add(nameQueue.poll());
				time += quantum;
			} else {
				time += timeQueue.poll();
				System.out.print(nameQueue.poll() + " ");
				System.out.println(time);
			}

