		while (time.size() != 0) {
			if (time.get(count) <= q) {
				total += time.get(count);
				System.out.printf("%s %d\n", name.get(count), total);
				time.remove(count);
				name.remove(count);
				count = count >= name.size() ? 0 : count;
			} else {
				total += q;
				time.set(count, time.get(count) - q);
				count = ++count >= name.size() ? 0 : count;

			}

		}

	}
}

