class Main{
	static int BinarySearch(int[] data, int key){
		int result = -1;
		int r = data.length-1;
		int l = 0;
		while(result == -1 && l <= r){
			int middle = (l+r)/2;
			if(data[middle]<key){
			    l = middle + 1;
			}else if(data[middle] > key){
				r = middle - 1;
			}else{
				result = middle ;
			}
		}
