public class Main {

    static int NOT_FOUND = 99999999;

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] sArr = new int[n + 1];
        for (int i = 0; i < n; i++) {
            sArr[i] = sc.nextInt();
        }

