             binarySearch(s, t[i]);
         }

         System.out.println(count);
    }

    public static void binarySearch(int[] s, int t){
        int hi = 0; int ti = s.length-1; //先頭のインデックス; 末尾のインデックス;
        int p;

        while(hi <= ti) {
            p = (hi + ti) / 2; //探索対象インデックス
            if(s[p] == t) {
                count++;
                break;
            } else if(s[p] < t) {
                hi = p + 1;
                continue;
            } else {
                ti = p - 1;
                continue;
            }
        }

        return;
    }
}

