	static int binSearch(int[] array, int n, int[] array1, int m) {
		int count = 0;
		for (int i = 0; i < m; i++) {
			int key = array1[i];
			int pl = 0;
			int pr = n - 1;
			do {
				int pc = (pr + pl) / 2;
			if (array[pc] == key) {
				count++;
				break;
			} else if (array[pc] < key){
				pl = pc + 1;
			} else {
				pr = pc - 1;
			}
			} while (pl <= pr);
		}
		return count;
	}
}

