    public static int search(int l, int r,int[] S, int target){
        int mid = (l+r)/2;
        if(mid == l || mid == r){
            return -1;
        }
        else if(S[r] < target || S[l] > target){
            return -1;
        }
        else if(S[mid] == target){
            return 1;
        }
        else if(S[r] == target){
            return 1;
        }
        else if(S[l] == target){
            return 1;
        }
        else if(S[mid] < target){
            return search(mid, r, S, target);
        }
        else{
            return search(l, mid, S, target);
        }
    }
