	public static boolean contains(int query, int[] check) {

		boolean containsInt = false;

		int low_index = 0;
		int high_index = check.length - 1;
		int middle_index = check.length / 2;
//		int iteration = 0;

		while(containsInt == false && high_index - low_index > 1) {

//			iteration++;
//			
//			System.out.println("----------------");
