//			System.out.println("H: " + high_index);

			if(check[middle_index] == query) {
				containsInt = true;
			}
			else if(check[middle_index] > query) {
				high_index = middle_index;
				middle_index = (high_index + low_index) / 2;
			}
			else if(check[middle_index] < query) {
				low_index = middle_index;
				middle_index = (high_index + low_index) / 2;
			}

		}

		if(check[high_index] == query) {
			containsInt = true;
		}

		return containsInt;

	}
