		String[] integerss = integers.split(" ");
		int a = Integer.parseInt(integerss[0]);
		int b = Integer.parseInt(integerss[1]);
		if (a < b) {
			return "a < b";
		} else if (a > b) {
			return "a > b";
		}
		return "a == b";
	}
