				break;
			}
			//最初の描画
			for(int i=0; i<W; i++) {
				System.out.printf("#");
			}
			System.out.printf("%n");

			//真ん中の描画
			for(int i=0; i<H-2; i++) {
				System.out.printf("#");

				for(int j=0; j<W-2; j++) {
					System.out.printf(".");
				}
				System.out.printf("#%n");
