class Tower{

    Floor[] floor = new Floor[3];

    Tower(){
        for(int i=0; i < floor.length; i++) floor[i] = new Floor();        
    }

    void index(int f ,int r ,int v){
        floor[f-1].addPeople(r, v);
    }

    String print(){
        String result = "";
        for(Floor a : floor){
            for(int b : a.room){
                result += " " + b;
            }
            result += "\n";
        }
        return result;
    }
}

class Floor{    
    int[] room = new int[10];

    Floor(){
        for(int i=0; i < room.length; i++) room[i] = 0;
    }

    void addPeople(int r ,int v){
        this.room[r-1] += v;
    }
}

