  Score(int midtermExam, int finalExam, int reExam) {
    this.midtermExam = midtermExam;
    this.finalExam = finalExam;
    this.reExam = reExam;
  }

  private int sumExamScore() {
    return midtermExam + finalExam;
  }

  String score() {
    if (midtermExam == -1 || finalExam == -1) {
      return "F";
    }
    if (sumExamScore() >= 80) {
      return "A";
    }
    if (sumExamScore() >= 65) {
      return "B";
    }
    if (sumExamScore() >= 50) {
      return "C";
    }
    if (sumExamScore() >= 30) {
      if (reExam >= 50) {
        return "C";
      } else {
        return "D";
      }
    }
    return "F";
  }
}

