    static long getMin(long a, long b, long c, long d) {
        long max = a * c;
        max = max(max, a * d);
        max = max(max, b * c);
        max = max(max, b * d);
        if ((a <= 0 && b >= 0) || (c <= 0 && d >= 0)) {
            max = max(max, 0);
        }
        return max;
    }

