	private static void solve(int d, int t, int s) {
		// TODO Auto-generated method stub
		//formula : d = vt
		if (s == 0) {
			if (d == 0) System.out.println("Yes");
			else System.out.println("No");
			return;
		}
		int res = s * t;
		if (res >= d) System.out.println("Yes");
		else System.out.println("No");
	}

}

