    int idx = 0;
    while (idx < 3) {
      int start = idx;
      while (idx < 3 && s.charAt(idx) == 'R') {
        idx++;
      }
      maxCount = Math.max(maxCount, idx - start);
      idx++;
    }
    System.out.println(maxCount);
  }

