                ac+=1;
            else if(s.equals("WA"))
                wa+=1;
            else if(s.equals("TLE"))
                tle++;
            else if(s.equals("RE"))
                re++;
        }
        pr.println("AC x "+ac);
        pr.println("WA x "+wa);
        pr.println("TLE x "+tle);
        pr.println("RE x "+re);
        pr.close();
