          if(p[i] > p[j]){
            sacrifice = p[i];
            p[i] = p[j];
            p[j] = sacrifice;
          }
        }
      }

      for(int i=0;i<K;i++){
        sum += p[i];
      }

      System.out.println(sum);
	}
}

