    void solve() throws IOException{
        long len = in.nextLong();

        long[] p = new long[15];
        p[0] = 1;
        for (int i = 1; i < 15; i++) p[i] = p[i-1]*26L;

        StringBuilder ans = new StringBuilder("");
        long cur = 1, cnt = 1;
        while (len != 0) {
            cnt*=26L;

            if (cnt < len) { 
                len -= cnt;
                cur++;
            } else {
                for (int i = 0; i < cur; i++) {
                    for (int j = 0; j < 26; j++) {
                        if (len-p[(int)cur-i-1] > 0) {
                            len -= p[(int)cur-i-1];
                            continue;
                        } else {
                            ans.append((char)(j+'a')+"");
                            break;
                        }
                    }
                }
                len = 0;
            }
        }
        out.println(ans);
    }

