		}
		for (int i = 0; i < len; i++) {
			xx = 0; r = 0;
			y = x; minus = 0;
			while (y <= N) {
				minus = y;
				r++;
				y += x;
			}
			N -= minus;
			x /= 26;
			//out.println(N + " " + x + " " + r);
