        long next = Long.parseLong(st.nextToken());
        if(next == 0){
          prod = 0;
          fail = false;
          break;
        }
        if(((long)Math.pow(10,18))/prod < next){
          fail = true;
        }
        else
          prod *= next;
      }
     if(fail)
       out.println(-1);
     else
       out.println(prod);
      out.close();
   }
}

