            }

            if (a == 0) {
                System.out.println(0);
                return;
            }

            list.add(a);

        }

        for (long a : list) {
            if (ans > root && a > root) {
                System.out.println(-1);
                return;
            }
            ans *= a;

            if (ans < 0 || ans > max) {
                System.out.println(-1);
                return;
            }
        }
        System.out.println(ans);
        in.close();
    }
}

