public class Main {

    private static boolean canBeAppended(String s1, String s2) {
        if (s1 == null || s2 == null) {
            return false;
        }

        int m = s1.length(), n = s2.length(), i = 0;
        while (i < m && i < n) {
            if (s1.charAt(i) != s2.charAt(i)) {
                return false;
            }
            i++;
        }

        return n != i && n - i <= 2;
    }

