public class Main {

    public static void main(String[] args) {
        int n = GetInput.getInt();
        HashMap<String , Integer> hashMap = new HashMap<>();
        while(n-->0) {
            String key = GetInput.getInputString().toString();
            if (hashMap.get(key) == null) {
                hashMap.put(key, 1);
                continue;
            }

            hashMap.replace(key, hashMap.get(key)+1);
        }
        System.out.println(hashMap.size());
    }


    private static long ff(long combinationSum) {
        return (long) (combinationSum%(Math.pow(10,9)+7));
    }

    private static int combinationSum(long n, int[] coins, int l) {
        if (n<0){
            return -1;
        }
        if (n==0){
            return l;
        }

        int coinCount = Integer.MAX_VALUE;
        for (int coin : coins) {
            int currCoin = combinationSum(n - coin, coins, l+1);
            if (currCoin == -1) {
                continue;
            }
            if (currCoin < coinCount) {
                coinCount = currCoin;
            }
        }
        if (coinCount == Integer.MAX_VALUE){
            return -1;
        }
        return coinCount;
    }
}

class GetInput {
