        TreeSet<Long> arr=new TreeSet<Long>();
        int cnt=0;
        for(long i=1;i*i<=num;i++){
            if(num%i==0){
                if(i*i==num){
                    cnt+=1;
                    arr.add(i);
                }
                else{
                    arr.add(i);arr.add(num/i);
                    cnt+=2;
                }
            }
        }
        return arr;
    }



