	private static int gcd(int a, int b) {
//		      辗转相减法
      while(a!=b) {
          if(a>b) {
              a=a-b;
          }else {
              b=b-a;
          }
      }
      return b;
	}


	private static int gcd(int a, int b, int c) {
		int gcd1 = gcd(a,b);
		return gcd(gcd1, c);
	}
