                    for (int i = oddNum - 1; i >= 1; i--){
                        outputNum = outputNum + i;
                    }
                    outputStr = String.valueOf(outputNum);
            }
            else {
                outputStr = "0";
            }
        }
        catch (Exception ex) {
            outputStr = "0";
        }

        System.out.println(outputStr);
        return;
    }

