    public static long lcm(long a, long b) {
        long c = a * b;
        long maxVal = Math.max(a, b);
        long minVal = Math.min(a, b);

        long tmp = 0;
        while ((tmp = maxVal % minVal) != 0) {
            maxVal = minVal;
            minVal = tmp;
        }

        return (c / minVal);
    }
