class Calc{

    private Integer n;
    private String s;
    Calc(Integer N, String S){
        this.n = N;
        this.s = S;
    }

    public String calc() {
        if (n % 2 != 0) {
            return "No";
        }
        int harf = n / 2;
        if (s.substring(0, harf).equals(s.substring(harf, s.length()))) {
            return "Yes";
        } else {
            return "No";
        }
    }
}

