      	int yesCnt = 0;
      	for(int i = 0; i < S.length(); i++){
      		if((i + 1) % 2 == 0){
            	// 偶数
              	if('L' == cArray[i] || 'U' == cArray[i] || 'D' == cArray[i]) {
                	yesCnt++;
