            	// 奇数
              	if('R' == cArray[i] || 'U' == cArray[i] || 'D' == cArray[i]) {
                	yesCnt++;
                }
            }
        }
      	if(yesCnt == S.length()){
          	System.out.println("Yes");
        } else {
        	System.out.println("No");  
        }
    }
}

