               if(b[i] <= b[i-1]){
                   answer += b[i];
               }
               //左側が一番小さい
               else if(b[i] > b[i-1]){
                   answer += b[i-1];
               }
        }
        answer += b[index-1];

        System.out.println(answer);

    }
}

