		long ans = 0;
		HashMap<String,Long> sk = new HashMap<String,Long>();
		for(int i=0;i<n;i++) {
			String s = sc.next();
			String[] po = s.split(""); 
			Arrays.sort(po);
			s =String.join("",po);
