			if(list[i] > list[i+1]) {
				return false;
			}
		}
		return true;
	}

	public static boolean Sort(int[] list){

		for(int i = list.length - 1;i>0;i--) {
			if(list[i] < list[i-1] ) {
				list[i-1] -= 1;
				if(list[i] < list[i-1]) {
					return false;
				}
			}
