                }
                p[j] = p[i];
                p[i] = tmp;
            }
        }
        System.out.println("NO");
    }

    public static boolean isAsc(int a[]) {
        for (int i =0;i<a.length-1;i++) {
            if (a[i] > a[i+1]) return false;
        }
        return true;
    }
}

