import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();

		long[] a = new long[N+1];
		for(int i=0; i<N+1; i++) {
			a[i] = sc.nextLong();
		}

		long[] b = new long[N];
		for(int i=0; i<N; i++) {
			b[i] = sc.nextLong();
		}

		sc.close();

		long cnt=0, tmp = 0;
		for(int i=0; i<N; i++) {

			if(i==0) {
				cnt += Math.min(a[i], b[i]);
				tmp = Math.min(a[i+1],b[i] - Math.min(a[i],b[i]));
				cnt += tmp;
			}

			if(i!=0) {
				cnt += Math.min(a[i] - tmp, b[i]);
				tmp = Math.min(a[i+1],b[i] - Math.min(a[i] - tmp, b[i]));
				cnt += tmp;
			}
		}

		System.out.println(cnt);
	}
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int [] arr = new int[n + 1];
        long x = 0;
        for (int i = 0; i < n + 1; i++) arr[i] = scanner.nextInt();
        for (int i = 0; i < n; i++) {
            int num = scanner.nextInt();
            int mo = Math.min(arr[i], num);
            arr[i] -= mo;
            num -= mo;
            x += mo;

            if (num != 0) {
                mo = Math.min(arr[i + 1], num);
                arr[i + 1] -= mo;
                num -= mo;
                x += mo;
            }
        }

        System.out.println(x);

