public class Main {

  private static long answer(long[] mons, long[] heroes) {
    long remain = mons[0];
    long sum = 0;
    for (int i = 0; i < heroes.length; i++) {
      long killed = Math.min(heroes[i], remain);
      long killed2 = Math.min(heroes[i] - killed, mons[i + 1]);
      remain = mons[i + 1] - killed2;
      sum += killed + killed2;
    }

    return sum;
  }

