    public int div(int n, int[] arr){
        Arrays.sort(arr);
        if (n==0) return 0;
        if (n%2==1) return 0;
        int middle = n/2 - 1;
        if (arr[middle] == arr[middle+1]){
            return 0;
        }

        return arr[middle+1] - arr[middle];
    }
}

