        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            if (n % 2 != 0)
                out.println(0);
            else {
                int[] a = new int[n];
                for (int i = 0; i < n; i++) {
                    a[i] = in.nextInt();
                }
                Arrays.sort(a);
                int mid = n / 2;
                if (a[mid] != a[mid - 1]) {
                    out.println(a[mid] - a[mid - 1]);
                } else {
                    out.println(0);
                }
            }
        }

