		long cBai = B/C - (A-1)/C;
		//Dの倍数の個数
		long dBai = B/D - (A-1)/D;
		//CとDの倍数の個数
		long cdBai = B/(lcm(C,D)) - (A-1)/lcm(C,D);
		//全体から引く
		long answer = (B - (A-1) - (cBai + dBai - cdBai));

		System.out.println(answer);

	}

	private static long lcm(long m, long n) {
	    return m * n / gcd(m, n);
	}

	private static long gcd(long m, long n) {
	    if(m < n) return gcd(n, m);
	    if(n == 0) return m;
	    return gcd(n, m % n);
	}
}

