        try (Scanner scanner = new Scanner(System.in)) {
            int N = scanner.nextInt();
            int[] vals = new int[N];
            for (int i = 0; i < N; i++) {
                vals[i] = scanner.nextInt();
            }
            return vals;
        }
    }
}

