          	min = j;
        }
    }
    int sum = 0;
    for(int j = 0;j < nums.length;j++){
    	if(j != min){
          if(nums[j] % 10 == 0){
             sum += nums[j];
          }else{
            sum += (nums[j] / 10) *10 + 10;
          }
        }
    }
