        int[][] A = new int[N][M];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                A[i][j] = in.nextInt();
            }
        }

        int ans = 0;
        for (int i = 0; i < N; i++) {
            int sum = C;
