		StringTokenizer t=new StringTokenizer(re.readLine());
		int a=Integer.parseInt(t.nextToken()),b=Integer.parseInt(t.nextToken()),k=Integer.parseInt(t.nextToken());
		int c=gcd(a,b),d=c;
		while(k>1) {
			if(c%--d==0)--k;
		}
		System.out.println(d);
	}
}

