    private static int execute(int[] arr, int length) {
        int x = 0;
        int y = Math.abs(arr[1] - arr[0]);
        for (int i = 2; i < length; i++) {
            int temp = y;
            y = Math.min(x + Math.abs(arr[i] - arr[i - 2]), y + Math.abs(arr[i] - arr[i - 1]));
            x = temp;
        }
        return y;
    }
