		for(int i = 0; i < N; ++i) {
			h[i] = in.nextInt();
		}
		int[] dp = new int[N];
		for(int i = 1; i < N; ++i) {
			dp[i] = dp[i - 1] + Math.abs(h[i] - h[i - 1]);
			if(i > 1) dp[i] = Math.min(dp[i], dp[i - 2] + Math.abs(h[i] - h[i - 2]));
		}
		System.out.println(dp[N - 1]);
		in.close();
	}
}

