	public static int frog2(int dp[], int a[], int N, int K) {
		if (N == 0)
			return 0;

		if (dp[N] != -1)
			return dp[N];
		int ans = Integer.MAX_VALUE;
		for (int i = 1; i <= K; i++) {
			if (N - i >= 0) {
				ans = Math.min(ans, (Math.abs(a[N] - a[N - i]) + frog2(dp, a, N - i, K)));
			}
		}
		dp[N] = ans;
		return ans;

	}

	static void sort(int[] a) {
		ArrayList<Integer> l = new ArrayList<>();
		for (int i : a)
			l.add(i);
		Collections.sort(l);
		for (int i = 0; i < a.length; i++)
			a[i] = l.get(i);
	}

