        }

        private static int jump(int[] costs, int k, int[] cache) {
                for(int i = 2 ; i < costs.length ; i++) {
                    for(int j = k ; j > 0 ; j--){
                        if(i-j >=0) {
                            cache[i] = Math.min(cache[i], cache[i-j]+(Math.abs(costs[i] - costs[i-j])));
