    static int[]arr;
    static int OO = (int)1e9+7;
    static int solve(int i)
    {
        if(i == n - 2) return Math.abs(arr[i] - arr[i + 1]);
        if(i == n - 1) return 0;
        if(memo[i] != null) return memo[i];

        int jump = OO;
        for (int j = 1; i + j <= Math.min(i + k , n - 1) ; j++)
            jump = Math.min(jump, Math.abs(arr[i] - arr[i + j]) + solve(i + j));
        return memo[i] = jump;
    }

