        if (str.charAt(str.length() - 1) == 'C') {
            return false;
        } else if (str.contains("C")) {
            str = str.substring(0, str.length() - 1);
            return (str.indexOf("C") == str.lastIndexOf("C"));
        } else {
            return false;
        }
    }
