		if(input.replaceAll("C","").length() == input.length()) {
			System.out.print("WA");
			return;
		}
		if(input.replaceAll("C","").length() < input.length() - 1) {
			System.out.print("WA");
			return;
		}
		if(!input.toLowerCase().equals(input.replaceAll("A","a").replaceAll("C","c"))) {
			System.out.print("WA");
			return;
		}
		System.out.print("AC");
	}

}

