			System.out.println("Yes");
		else
			System.out.println("No");
	}

	public static StringBuilder Rotate(StringBuilder str) {
		int len=str.length();
		char t=str.charAt(0);
		for(int i=0;i<len-1;i++) {
			str.setCharAt(i,str.charAt(i+1));			
		}
		str.setCharAt(len-1,t);
		return str;
	}
}

