			a[Integer.parseInt(as2[i])] = 1;
		}
		System.out.println(solve());
	}

	private static int solve() {
		int ans0 = 0;
		int ansN = 0;
		for(int i = x; i < n; i++) {

			ans0 += a[i];
		}
		if(ans0==0) return 0;
		for(int i = x; i > 0; i--) {
			ansN += a[i];
		}
		if(ans0>ansN) {
			return ansN;
		} else {
			return ans0;
		}

	}



