            if(isKaibunNum(i)){
                count += 1;
            }
        }
        out.print(count);
    }

    private static boolean isKaibunNum(int n){
        CharSequence sb = new StringBuilder(String.valueOf(n));
        int l = sb.length();

        if(l==1){
            return true;
        }
        int checkCount = l/2;

        for (int i = 0; i < checkCount ; i++) {
            char left = sb.charAt(i);
            char right = sb.charAt(l-1-i);
            if(left != right){
                return false;
            }
        }
        return true;
    }
}

