        ArrayList<Integer> fir = new ArrayList<Integer>();
        ArrayList<Integer> sec = new ArrayList<Integer>();
        String[] input1 = sc.nextLine().split(" ");
        String[] input2 = sc.nextLine().split(" ");
        int ans = 0;
        for(int i=0 ; i<n ; i++){
            fir.add(Integer.parseInt(input1[i]));
