    static int get(int n,int sign , ArrayList<Integer> a , ArrayList<Integer> b){
        int sum = 0;
        for(int i = 0;i <= sign; i++){
            sum += a.get(i);
        }
        for(int i = sign; i < n; i++){
            sum += b.get(i);
        }
        return sum;
    }
}

