			int y = sc.nextInt();
			checkPoints[i][0] = t;
			checkPoints[i][1] = x;
			checkPoints[i][2] = y;
			if (isAbleToGo(startPoint, checkPoints[i])) {
				startPoint = checkPoints[i];
			} else {
