            if (A <= sumDigits && sumDigits <= B) {
                res += i;
            }
        }
        System.out.println(res);
    }

    private static int calcSumOfDigits(int i) {
        int tmp = i;
        int sumDigits = 0;
        while (tmp > 0) {
            sumDigits += tmp % 10;
            tmp /= 10;
        }
        return sumDigits;
    }
}

