            for (int j = 0; j < length; j++) {
                // 場所ごとの組み合わせで対応が異なる処理を入れる
                if ((i >> j) % 2 == 0) {
                    // "-"を入れる場合
                    answer += "-" + strArray[j + 1];
                    ansNum -= Integer.valueOf(strArray[j + 1]);
                } else {
                    // "+"を入れる場合
                    answer += "+" + strArray[j + 1];
                    ansNum += Integer.valueOf(strArray[j + 1]);
                }
            }
            if (ansNum == 7) {
                answer += "=7";
                break;
            }
        }

        System.out.println(answer);

        sc.close();
    }
}

