public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		//入力 A: Alice、B:Bob
		int A_min = sc.nextInt();
		int A_max = sc.nextInt();
		int B_min = sc.nextInt();
		int B_max = sc.nextInt();
		int answer = 0;

		//Aの最小値よりBの最大値が小さい、もしくは、Aの最大値よりBの最小値が大きい場合：区間の重複はないため答えは0
		if (A_min > B_max || A_max < B_min) {
			answer = 0;
		}

		//Aの最小値よりBの最小値が小さく、Aの最大値よりBの最大値が小さい場合：Aの最小値～Bの最大値まで重複
		else if (A_min >= B_min && A_max >= B_max) {
			answer = B_max - A_min;
		}

		//Aの最小値よりBの最小値が小さく、Aの最大値よりBの最大値が大きい場合：Aの最小値～Aの最大値まで重複
		else if (A_min >= B_min && A_max <= B_max) {
			answer = A_max - A_min;
		}

		//Aの最小値よりBの最小値が大きく、Aの最大値よりBの最大値が小さい場合：Bの最小値～Bの最大値まで重複
		else if (A_min <= B_min && A_max >= B_max) {
			answer = B_max - B_min;
		}

		//Aの最小値よりBの最小値が大きく、Aの最大値よりBの最大値が大きい場合：Bの最小値～Aの最大値まで重複
		else {
			answer = A_max - B_min;
		}
//		else if (A_min <= B_min && A_max >= B_max) {
//			answer = A_max - B_min;
//		}

		System.out.println(answer);
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.InputMismatchException;
import java.util.List;
import java.util.Map;

public class Main {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        new Main().calc();
    }

    int calcTime(int A, int B, int C, int D) {
        // C <-> DがA <-> Bの範囲と重複しない場合
        if (B <= C || D <= A) {
            return 0;
        }

        // CがAより小さい場合
        if (C < A) {
            // DがB以下なら，A<->Dが重複範囲となる
            if (D <= B) {
                return D - A;
            }
            // DがBより大きければ，A<->Bが重複範囲となる
            else {
                return B - A;
            }
        }
        // 残るケースはCがAとBの間にある場合のみ
        else {
            // DがB以下なら，C<->Dが重複範囲となる
            if (D <= B) {
                return D - C;
            }
            // DがBより大きければ，C<->Bが重複範囲となる
            else {
                return B - C;
            }

        }

    }

    public void calc() {
        int A = in.nextInt();
        int B = in.nextInt();
        int C = in.nextInt();
        int D = in.nextInt();

        out.println(calcTime(A, B, C, D));
        out.close();
    }

    class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++)
                array[i] = nextInt();

            return array;
        }

        int[][] nextIntMap(int n, int m) {
            int[][] map = new int[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextIntArray(m);
            }
            return map;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        long[] nextLongArray(int n) {
            long[] array = new long[n];
            for (int i = 0; i < n; i++)
                array[i] = nextLong();

            return array;
        }

        long[][] nextLongMap(int n, int m) {
            long[][] map = new long[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextLongArray(m);
            }
            return map;
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        double[] nextDoubleArray(int n) {
            double[] array = new double[n];
            for (int i = 0; i < n; i++)
                array[i] = nextDouble();

            return array;
        }

        double[][] nextDoubleMap(int n, int m) {
            double[][] map = new double[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextDoubleArray(m);
            }
            return map;
        }

        String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        String[] nextStringArray(int n) {
            String[] array = new String[n];
            for (int i = 0; i < n; i++)
                array[i] = next();

            return array;
        }

        String nextLine() {
            int c = read();
            while (isEndline(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

