            int cnt = 0;
            while (temp % 2 == 0) {
                temp /= 2;
                ++cnt;
            }
            if (cnt >= cnt1) {
                cnt1 = cnt;
                ans = i;
            }
        }
        out.println(ans);
        out.close();
    }

}

