    public void solve(String s) {
        String ans = "";
        int count = 0;
        for (int i = s.length() - 1; i >= 0; i--) {
            if (s.charAt(i) == 'B') {
                count++;
            } else {
                if (count > 0) {
                    count--;
                    continue;
                } else {
                    ans = ans.concat(Character.toString(s.charAt(i)));
                }
            }
        }
        Main.output.append(ans);
